const express = require('express');
const multer = require('multer');
const dns = require('dns');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const app = express();

// Circuit breaker state
const circuitBreaker = {
  failures: 0,
  threshold: 5,
  timeout: 30000,
  lastFailure: null,
  state: 'CLOSED' // CLOSED, OPEN, HALF_OPEN
};

function checkCircuit() {
  if (circuitBreaker.state === 'OPEN') {
    const elapsed = Date.now() - circuitBreaker.lastFailure;
    if (elapsed > circuitBreaker.timeout) {
      circuitBreaker.state = 'HALF_OPEN';
      return true;
    }
    return false;
  }
  return true;
}

function recordSuccess() {
  circuitBreaker.failures = 0;
  circuitBreaker.state = 'CLOSED';
}

function recordFailure() {
  circuitBreaker.failures++;
  circuitBreaker.lastFailure = Date.now();
  if (circuitBreaker.failures >= circuitBreaker.threshold) {
    circuitBreaker.state = 'OPEN';
  }
}

// DNS resolution with circuit breaker
async function resolveDomain(domain) {
  if (!checkCircuit()) {
    throw new Error('Circuit breaker is OPEN');
  }
  return new Promise((resolve, reject) => {
    dns.resolve4(domain, (err, addresses) => {
      if (err) {
        recordFailure();
        reject(err);
      } else {
        recordSuccess();
        resolve(addresses);
      }
    });
  });
}

// Allowed MIME types for zone file uploads
const ALLOWED_MIMES = ['text/plain', 'application/octet-stream', 'text/dns'];
const ALLOWED_EXTENSIONS = ['.zone', '.txt', '.conf'];

// File filter that validates based on DNS resolution of origin
const fileFilter = async (req, file, cb) => {
  try {
    const ext = path.extname(file.originalname).toLowerCase();
    const mimeOk = ALLOWED_MIMES.includes(file.mimetype);
    const extOk = ALLOWED_EXTENSIONS.includes(ext);

    if (!mimeOk || !extOk) {
      return cb(new Error('Invalid file type'), false);
    }
    cb(null, true);
  } catch (err) {
    cb(err, false);
  }
};

// Storage configuration with sanitized filename
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = path.join(__dirname, 'uploads', 'zones');
    fs.mkdirSync(uploadDir, { recursive: true });
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const hash = crypto.createHash('sha256')
      .update(file.originalname + Date.now())
      .digest('hex');
    const ext = path.extname(file.originalname).toLowerCase();
    cb(null, `${hash}${ext}`);
  }
});

const upload = multer({
  storage: storage,
  fileFilter: fileFilter,
  limits: { fileSize: 10 * 1024 * 1024 }
});

// Zone file upload endpoint with DNS verification
app.post('/api/zones/upload', upload.single('zonefile'), async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No file uploaded' });
    }

    const domain = req.body.domain;
    if (!domain || !/^[a-zA-Z0-9][a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$/.test(domain)) {
      // Clean up uploaded file if domain validation fails
      fs.unlinkSync(req.file.path);
      return res.status(400).json({ error: 'Invalid domain format' });
    }

    // Verify domain resolves before accepting zone file
    let addresses;
    try {
      addresses = await resolveDomain(domain);
    } catch (dnsErr) {
      // Circuit breaker OPEN or DNS failure - file already saved by multer
      // In degraded mode, we keep the file for later processing
      if (circuitBreaker.state === 'OPEN' || circuitBreaker.state === 'HALF_OPEN') {
        return res.status(202).json({
          message: 'File queued for processing (DNS unavailable)',
          filename: req.file.filename,
          status: 'pending'
        });
      }
      fs.unlinkSync(req.file.path);
      return res.status(422).json({ error: 'Domain does not resolve' });
    }

    // Parse and validate zone file content
    const content = fs.readFileSync(req.file.path, 'utf8');
    const zoneValid = validateZoneContent(content, domain);

    if (!zoneValid) {
      fs.unlinkSync(req.file.path);
      return res.status(422).json({ error: 'Invalid zone file content' });
    }

    res.json({
      message: 'Zone file uploaded successfully',
      filename: req.file.filename,
      domain: domain,
      addresses: addresses
    });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

function validateZoneContent(content, domain) {
  const lines = content.split('\n').filter(l => l.trim() && !l.startsWith(';'));
  if (lines.length === 0) return false;

  // Check for SOA record
  const hasSOA = lines.some(l => l.includes('SOA'));
  // Verify domain reference in zone
  const hasDomainRef = lines.some(l => l.includes(domain) || l.includes('$ORIGIN'));

  return hasSOA && hasDomainRef;
}

// DNS lookup endpoint
app.get('/api/resolve/:domain', async (req, res) => {
  try {
    const domain = req.params.domain;
    if (!/^[a-zA-Z0-9][a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$/.test(domain)) {
      return res.status(400).json({ error: 'Invalid domain' });
    }
    const addresses = await resolveDomain(domain);
    res.json({ domain, addresses });
  } catch (err) {
    res.status(503).json({ error: err.message });
  }
});

app.listen(3000, () => console.log('DNS Zone Manager running on port 3000'));

module.exports = app;
